postconditions.probe:
awk '
function trim(s) {
  sub(/^[[:space:]]+/, "", s)
  sub(/[[:space:]]+$/, "", s)
  return s
}
FNR==NR {
  line=trim($0)
  if (line == "" || line ~ /^#/) next
  pos=index(line, "=")
  if (pos == 0) next
  old=trim(substr(line, 1, pos-1))
  new=trim(substr(line, pos+1))
  if (old != "" && new != "") map[old]=new
  next
}
{
  line=$0
  pos=index(line, "=")
  if (pos == 0) next
  key=trim(substr(line, 1, pos-1))
  if (key != "") count[key]++
}
END {
  for (old in map) {
    if (count[old] > 0) exit 1
  }
  exit 0
}
' config/renames.conf config/settings.conf

{
  sed 's/^/MAP:/' config/renames.conf
  git show HEAD^:config/settings.conf | sed 's/^/OLD:/'
  git show HEAD:config/settings.conf | sed 's/^/NEW:/'
} | awk '
function trim(s) {
  sub(/^[[:space:]]+/, "", s)
  sub(/[[:space:]]+$/, "", s)
  return s
}
function parse(line, counts, vals,    pos, key, val) {
  pos=index(line, "=")
  if (pos == 0) return
  key=trim(substr(line, 1, pos-1))
  if (key == "") return
  val=trim(substr(line, pos+1))
  counts[key]++
  vals[key]=val
}
{
  type=substr($0, 1, 4)
  line=substr($0, 5)
  if (type == "MAP:") {
    line=trim(line)
    if (line == "" || line ~ /^#/) next
    pos=index(line, "=")
    if (pos == 0) next
    old=trim(substr(line, 1, pos-1))
    new=trim(substr(line, pos+1))
    if (old != "" && new != "") map[old]=new
    next
  }
  if (type == "OLD:") { parse(line, oldc, oldv); next }
  if (type == "NEW:") { parse(line, newc, newv); next }
}
END {
  for (old in map) {
    if (oldc[old] > 0) {
      new=map[old]
      if (oldc[old] != 1) exit 1
      if (newc[old] > 0) exit 1
      if (newc[new] != 1) exit 1
      if (oldv[old] != newv[new]) exit 1
    } else {
      if (newc[old] > 0) exit 1
    }
  }
  for (key in oldc) {
    if (key in map) continue
    if (newc[key] != oldc[key]) exit 1
    if (oldv[key] != newv[key]) exit 1
  }
  for (key in newc) {
    if (key in oldc) continue
    is_target=0
    for (old in map) {
      if (map[old] == key) {
        is_target=1
        if (oldc[old] == 0) exit 1
        break
      }
    }
    if (!is_target) exit 1
  }
  exit 0
}
'

preconditions.probe:
awk '
function trim(s) {
  sub(/^[[:space:]]+/, "", s)
  sub(/[[:space:]]+$/, "", s)
  return s
}
FNR==NR {
  line=trim($0)
  if (line == "" || line ~ /^#/) next
  pos=index(line, "=")
  if (pos == 0) next
  old=trim(substr(line, 1, pos-1))
  new=trim(substr(line, pos+1))
  if (old != "" && new != "") map[old]=new
  next
}
{
  line=$0
  pos=index(line, "=")
  if (pos == 0) next
  key=trim(substr(line, 1, pos-1))
  if (key != "") count[key]++
}
END {
  found=0
  for (old in map) {
    if ((map[old]) in map) exit 1
    if (count[old] > 1) exit 1
    if (count[old] == 1) {
      new=map[old]
      if (count[new] > 0) exit 1
      if (used[new]) exit 1
      used[new]=1
      found=1
    }
  }
  exit(found ? 0 : 1)
}
' config/renames.conf config/settings.conf
